from pathlib import Path
import py_compile

ROOT = Path.cwd()
SUB = ROOT / "qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot"
RUN22D = ROOT / "run_qarb_022d_persistent_mriya_style_profit_runtime.py"

if not RUN22D.is_file():
    raise SystemExit("[FAIL] certified QARB-022D runner missing: " + str(RUN22D))

runner_text = RUN22D.read_text(encoding="utf-8", errors="replace")
if "qarb" not in runner_text.lower():
    raise SystemExit("[FAIL] QARB-022D runner contract unreadable")

if not SUB.is_dir():
    raise SystemExit("[FAIL] qarb_clean_bot subsystem missing: " + str(SUB))

MOD = SUB / "qarb_023b_v0_alt_atomic_packet_compaction.py"
MOD.write_text('from __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom itertools import combinations\nfrom typing import Any, Iterable, Sequence\n\nPACKET_LIMIT = 1232\nexecution_authority = False\n\n\n@dataclass(frozen=True)\nclass Candidate:\n    label: str\n    size_bytes: int\n    tx: Any\n    lookup_table_count: int\n\n\n@dataclass(frozen=True)\nclass CompactionResult:\n    ok: bool\n    status: str\n    best: Candidate | None\n    attempted: tuple[tuple[str, int], ...]\n    over_by: int\n    execution_authority: bool = False\n\n\ndef packet_size(tx: Any) -> int:\n    return len(bytes(tx))\n\n\ndef choose_smallest(candidates: Iterable[Candidate]) -> CompactionResult:\n    rows = tuple(candidates)\n    if not rows:\n        return CompactionResult(False, "NO_CANDIDATE", None, (), 0)\n    best = min(rows, key=lambda x: x.size_bytes)\n    attempted = tuple((x.label, x.size_bytes) for x in rows)\n    if best.size_bytes <= PACKET_LIMIT:\n        return CompactionResult(True, "PACKET_FITS", best, attempted, 0)\n    return CompactionResult(\n        False,\n        "ATOMIC_TX_TOO_LARGE",\n        best,\n        attempted,\n        best.size_bytes - PACKET_LIMIT,\n    )\n\n\ndef _compile_v0(payer: Any, recent_blockhash: Any, instructions: Sequence[Any],\n                lookup_tables: Sequence[Any]) -> Any:\n    try:\n        from solders.message import MessageV0\n        from solders.signature import Signature\n        from solders.transaction import VersionedTransaction\n    except Exception as exc:\n        raise RuntimeError("SOLDERS_REQUIRED_FOR_V0_COMPILE") from exc\n\n    msg = MessageV0.try_compile(\n        payer,\n        list(instructions),\n        list(lookup_tables),\n        recent_blockhash,\n    )\n    sigs = [Signature.default() for _ in range(msg.header.num_required_signatures)]\n    return VersionedTransaction.populate(msg, sigs)\n\n\ndef compile_best_v0(\n    payer: Any,\n    recent_blockhash: Any,\n    instructions: Sequence[Any],\n    lookup_tables: Sequence[Any],\n    max_lookup_tables: int = 3,\n) -> CompactionResult:\n    candidates: list[Candidate] = []\n    errors: list[tuple[str, int]] = []\n\n    table_sets: list[tuple[Any, ...]] = [()]\n    limit = min(max(0, int(max_lookup_tables)), len(lookup_tables))\n    for n in range(1, limit + 1):\n        table_sets.extend(combinations(lookup_tables, n))\n\n    for tables in table_sets:\n        label = "V0_NO_ALT" if not tables else f"V0_ALT_{len(tables)}"\n        try:\n            tx = _compile_v0(payer, recent_blockhash, instructions, tables)\n            candidates.append(Candidate(label, packet_size(tx), tx, len(tables)))\n        except Exception:\n            errors.append((label, 10**9))\n\n    result = choose_smallest(candidates)\n    if result.ok or candidates:\n        return result\n    return CompactionResult(\n        False,\n        "V0_COMPILE_FAILED",\n        None,\n        tuple(errors),\n        0,\n    )\n\n\ndef format_result(result: CompactionResult) -> str:\n    if result.best is None:\n        return (\n            f"[ATOMIC_PACKET] status={result.status} "\n            f"limit={PACKET_LIMIT} execution_authority=FALSE"\n        )\n    return (\n        f"[ATOMIC_PACKET] status={result.status} "\n        f"candidate={result.best.label} bytes={result.best.size_bytes} "\n        f"limit={PACKET_LIMIT} over_by={result.over_by} "\n        f"alts={result.best.lookup_table_count} execution_authority=FALSE"\n    )\n', encoding="utf-8")

TEST = ROOT / "test_qarb_023b_v0_alt_atomic_packet_compaction.py"
TEST.write_text('import inspect\nimport unittest\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import (\n    qarb_023b_v0_alt_atomic_packet_compaction as q,\n)\n\n\nclass FakeTx:\n    def __init__(self, n):\n        self.n = n\n\n    def __bytes__(self):\n        return b"x" * self.n\n\n\nclass T(unittest.TestCase):\n    def test_known_1257_failure(self):\n        r = q.choose_smallest([\n            q.Candidate("PUMP_METEORA_ONLY", 1257, FakeTx(1257), 0)\n        ])\n        self.assertFalse(r.ok)\n        self.assertEqual(r.status, "ATOMIC_TX_TOO_LARGE")\n        self.assertEqual(r.over_by, 25)\n        print("[PASS] known 1257-byte candidate fails closed by exactly 25 bytes")\n\n    def test_compacted_packet_admitted(self):\n        r = q.choose_smallest([\n            q.Candidate("LEGACY", 1257, FakeTx(1257), 0),\n            q.Candidate("V0_ALT_1", 1188, FakeTx(1188), 1),\n        ])\n        self.assertTrue(r.ok)\n        self.assertEqual(r.best.label, "V0_ALT_1")\n        self.assertEqual(r.best.size_bytes, 1188)\n        print("[PASS] compact <=1232-byte packet admitted")\n\n    def test_smallest_candidate_selected(self):\n        r = q.choose_smallest([\n            q.Candidate("A", 1210, FakeTx(1210), 1),\n            q.Candidate("B", 1192, FakeTx(1192), 2),\n        ])\n        self.assertEqual(r.best.label, "B")\n        print("[PASS] smallest candidate selected deterministically")\n\n    def test_no_hot_io(self):\n        src = inspect.getsource(q.compile_best_v0)\n        for token in ("urlopen(", "requests.", "open(", "Path(", "sleep("):\n            self.assertNotIn(token, src)\n        print("[PASS] no REST/RPC/filesystem/sleep in compaction hot function")\n\n    def test_execution_authority_false(self):\n        self.assertIs(q.execution_authority, False)\n        print("[PASS] execution_authority=FALSE")\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n', encoding="utf-8")

RUN = ROOT / "run_qarb_023b_v0_alt_atomic_packet_compaction.py"
RUN.write_text('from qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import qarb_023b_v0_alt_atomic_packet_compaction as q\n\nprint("[QARB-023B] V0/ALT ATOMIC PACKET COMPACTION")\nprint("[UPSTREAM] QARB-022D certified runner present")\nprint("[KNOWN_DEFECT] stripped PumpSwap+Meteora packet=1257 bytes")\nprint("[LIMIT] 1232 bytes")\nprint("[TARGET] compact exact atomic candidate before real simulateTransaction")\nprint("[HOT_IO] none")\nprint("[MODE] compose/size gate only execution_authority=FALSE")\n', encoding="utf-8")

for p in (MOD, TEST, RUN):
    py_compile.compile(str(p), doraise=True)

print("[PASS] QARB-023B V0/ALT atomic packet compaction installed")
print("[UPSTREAM] certified QARB-022D runner verified")
print("[DEFECT] stripped PumpSwap+Meteora atomic candidate=1257 bytes")
print("[LIMIT] Solana packet ceiling=1232 bytes; required reduction=25 bytes")
print("[FIX] local V0 compiler can test supplied Address Lookup Tables and select smallest legal packet")
print("[HOT_IO] no REST/RPC/filesystem/sleep in compaction path")
print("[MODE] compose/size gate only execution_authority=FALSE")
